import xml.etree.ElementTree as ET

from taf.rnc.oms.nwi3.exceptions import XMLObjectNotFoundException


class OMSConfigManager(object):

    def __init__(self, config_path):
        self.config_path = config_path
        self.tree = ET.parse(config_path)

    def set_rnc_number(self, rnc_number):
        """
        Method for setting RNC number via XPath in Pegasus config file

        :param rnc_number: Number of RNC which will be accessed
        :type rnc_number: str
        """
        self._find_and_set_xml_value('.//RNC_Number', rnc_number)

    def set_oms_ip(self, oms_ip):
        """
        Method for setting OMS IP address via XPath in Pegasus config file

        :param oms_ip: IP of OMS which will be accessed
        :type oms_ip: str
        """
        self._find_and_set_xml_value('.//OMSIPAddress', oms_ip)

    def set_oms_credentials(self, oms_username, oms_password):
        """
        Method for setting OMS credentials via XPath in Pegasus config file

        :param oms_username: Username used for OMS login
        :type oms_username: str
        :param oms_password: Password used for OMS login
        :type oms_password: str
        """
        self._find_and_set_xml_value('.//OMSUserName', oms_username)
        self._find_and_set_xml_value('.//OMSPassword', oms_password)

    def _find_and_set_xml_value(self, xpath, value):
        value = str(value)
        try:
            self.tree.find(xpath).text = value
        except AttributeError:
            raise XMLObjectNotFoundException('Path {xpath} not found inside {config}'.format(xpath=xpath,
                                                                                             config=self.config_path))
        else:
            self.tree.write(self.config_path)
